import re

def escape(markup):
    pattern = re.compile(r"(\\\\*)(\[[a-z#/@][^[]*?])|(\\\\+)")
    def escape_backslashes(match):
        if match.group(3):
            return match.group(3) * 2
        backslashes, text = match.group(1), match.group(2)
        return f"{backslashes}{backslashes}\\{text}"

    return pattern.sub(escape_backslashes, markup)

test_cases = [
    (r"Hello [tag]", r"Hello \[tag]"),
    (r"Hello \[tag]", r"Hello \\\[tag]"),
    (r"Hello \\ [tag]", r"Hello \\ \[tag]"),
    ("Hello " + "\\", "Hello " + "\\\\"),
    ("Hello " + "\\\\", "Hello " + "\\\\\\\\"),
]

for input_str, expected in test_cases:
    result = escape(input_str)
    print(f"Input: {input_str!r} | Expected: {expected!r} | Result: {result!r} | {'OK' if result == expected else 'FAIL'}")

